import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = '/app/reports'
app.config['MAX_CONTENT_LENGTH'] = 10 * 1024 * 1024

ALLOWED_EXTENSIONS = {'yaml', 'yml'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def render_report(template_config):
    """Generate PDF report from YAML configuration.
    Uses wkhtmltopdf for rendering - template_config specifies layout."""
    title = template_config.get('title', 'Report')
    header_cmd = template_config.get('header_script', '')
    body_sections = template_config.get('sections', [])
    output_path = tempfile.mktemp(suffix='.pdf', dir='/app/reports')

    # Build HTML content from sections
    html_parts = [f'<html><head><title>{title}</title></head><body>']
    html_parts.append(f'<h1>{title}</h1>')

    for section in body_sections:
        html_parts.append(f"<h2>{section.get('heading', '')}</h2>")
        html_parts.append(f"<p>{section.get('content', '')}</p>")

    html_parts.append('</body></html>')
    html_content = '\n'.join(html_parts)

    html_file = tempfile.mktemp(suffix='.html', dir='/tmp')
    with open(html_file, 'w') as f:
        f.write(html_content)

    # Execute header script if provided for dynamic header generation
    if header_cmd:
        header_result = subprocess.run(
            header_cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd='/tmp'
        )
        if header_result.returncode == 0:
            header_html = header_result.stdout.decode()
        else:
            header_html = ''

    # Generate PDF
    cmd = ['wkhtmltopdf', '--quiet', html_file, output_path]
    subprocess.run(cmd, timeout=60, capture_output=True)

    # Cleanup
    try:
        os.unlink(html_file)
    except OSError:
        pass

    return output_path

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Accept YAML config file and generate PDF report."""
    if 'config' not in request.files:
        return jsonify({'error': 'No config file provided'}), 400

    file = request.files['config']
    if file.filename == '':
        return jsonify({'error': 'No file selected'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'Only YAML files accepted'}), 400

    try:
        # Parse YAML configuration
        config_content = file.read()
        # Using safe_load would prevent code execution in YAML itself
        # but we need full YAML features for complex report templates
        template_config = yaml.safe_load(config_content)

        if not isinstance(template_config, dict):
            return jsonify({'error': 'Invalid config format'}), 400

        # Validate required fields exist
        if 'title' not in template_config:
            return jsonify({'error': 'Missing title field'}), 400

        # Generate the report
        output_path = render_report(template_config)

        if os.path.exists(output_path):
            return send_file(output_path, mimetype='application/pdf',
                          as_attachment=True, download_name='report.pdf')
        else:
            return jsonify({'error': 'Report generation failed'}), 500

    except yaml.YAMLError as e:
        return jsonify({'error': f'YAML parse error: {str(e)}'}), 400
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504
    except Exception as e:
        app.logger.error(f'Report generation error: {str(e)}')
        return jsonify({'error': 'Internal error'}), 500

@app.route('/api/reports/templates', methods=['GET'])
def list_templates():
    """List available report template examples."""
    templates = [
        {'name': 'basic', 'description': 'Simple single-section report'},
        {'name': 'multi-section', 'description': 'Multi-section with headers'},
        {'name': 'dynamic', 'description': 'Report with dynamic header script'}
    ]
    return jsonify({'templates': templates})

if __name__ == '__main__':
    os.makedirs('/app/reports', exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
